async function rpc(service: string, method: string, ...args: unknown[]) {
  const r = await fetch(`${ENV.erpUrl}/jsonrpc`, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ jsonrpc: "2.0", method: "call", params: { service, method, args } }),
  });
  const body: any = await r.json();
  if (body.error) throw new Error(body.error.data?.message ?? body.error.message);
  return body.result;
}
async function erpRead(model: string, method: string, args: unknown[], kwargs: object = {}) {
  const uid = await rpc("common", "login", ENV.erpDb, ENV.admin.login, ENV.admin.password);
  return rpc("object", "execute_kw", ENV.erpDb, uid, ENV.admin.password, model, method, args, kwargs);
}

test("CP-005 A mill breakdown reported by the shift supervisor reaches maintenance as an urgent corrective request", async ({ page }) => {
  const c = loadCase("CP-005");
  const user = ENV.roles[c.data.role];
  const subject = `${c.data.subject} · ${runTag()}`;
  const stars = Number(/\((\d) stars?\)/.exec(c.data.priority)![1]);
  // Priority n stars is selection key "n"; its label names the star radio on screen.
  const { priority } = await erpRead("maintenance.request", "fields_get", [["priority"]], { attributes: ["selection"] });
  const starLabel = (priority.selection as [string, string][]).find(([k]) => k === String(stars))![1];
  const [supervisor] = await erpRead("res.users", "search_read", [[["login", "=", user.login]]], { fields: ["name"] });

  await test.step(c.steps[0], async () => {
    await page.goto(`${ENV.erpUrl}/web/login?db=${ENV.erpDb}`);
    await page.getByRole("textbox", { name: /email|login/i }).fill(user.login);
    await page.getByRole("textbox", { name: /password/i }).fill(user.password);
    await page.getByRole("button", { name: /log in/i }).click();
    await page.waitForURL(/\/odoo/);

    await page.getByTitle("Home Menu").click();
    await page.getByRole("menuitem", { name: "Maintenance" }).click();
    await page.getByRole("button", { name: "Maintenance" }).click();
    await page.getByRole("menuitem", { name: "Maintenance Requests" }).click();
    await page.getByRole("button", { name: "New" }).click();
    await page.getByRole("textbox", { name: "Request" }).fill(subject);
    await page.getByRole("combobox", { name: "Equipment" }).fill(c.data.equipment);
    await page.getByRole("option", { name: c.data.equipment }).click();
  });

  await test.step(c.steps[1], async () => {
    await page.getByRole("radio", { name: c.data.type }).click();
    // The priority widget saves the record on click.
    await page.getByRole("radio", { name: starLabel }).click();
    await expect(page).toHaveURL(/\/odoo\/maintenance-requests\/\d+/);
    await expect(page.getByRole("button", { name: "Save manually" })).toBeHidden();
  });

  await test.step(c.expected_results[0], async () => {
    await expect(page.getByRole("radio", { name: "New Request" })).toBeChecked();
    await expect(page.getByRole("radio", { name: starLabel })).toBeChecked();
  });

  await test.step(c.expected_results[1], async () => {
    await expect(page.getByRole("combobox", { name: "Team" })).toHaveValue("Rolling mill maintenance");
  });

  await test.step(c.expected_results[2], async () => {
    // The form has no requester field; the creation message in the chatter names its author.
    await expect(
      page.getByRole("group", { name: "System notification" }).filter({ hasText: "Maintenance Request created" }),
    ).toContainText(supervisor.name);
  });

  await test.step(c.data_validation[0], async () => {
    const find = async () =>
      (await erpRead("maintenance.request", "search_read", [[["name", "=", subject]]], {
        fields: ["maintenance_type", "priority", "stage_id", "maintenance_team_id", "owner_user_id"],
      }))[0];
    const req = await eventually(find, (r) => r?.priority === String(stars));
    expect(req, `maintenance.request "${subject}"`).toBeDefined();
    expect(req.maintenance_type).toBe(c.data.type.toLowerCase());
    expect(req.priority).toBe(String(stars));
    expect(req.stage_id[1]).toBe("New Request");
    expect(req.maintenance_team_id[1]).toBe("Rolling mill maintenance");
    expect(req.owner_user_id[0]).toBe(supervisor.id);
  });
});

