import { test, expect } from "@playwright/test";
import { ENV } from "./support/index.ts";

test.describe("Maintenance · Breakdown report", () => {
  test("CP-005 A mill breakdown reported by the shift supervisor reaches maintenance as an urgent corrective request", async ({ page }) => {
    // Seed state: logged in as the sales rep.
    await page.goto(`${ENV.erpUrl}/web/login?db=${ENV.erpDb}`);
    await page.getByRole("textbox", { name: /email|login/i }).fill(ENV.sales.login);
    await page.getByRole("textbox", { name: /password/i }).fill(ENV.sales.password);
    await page.getByRole("button", { name: /log in/i }).click();
    await page.waitForURL(/\/odoo/);

    // 1. Log into the ERP as the shift supervisor (log out first).
    await page.getByRole("button", { name: /User/ }).click();
    await page.getByRole("menuitem", { name: "Log out" }).click();
    await page.getByRole("textbox", { name: /Email/ }).fill("shift.supervisor");
    await page.getByRole("textbox", { name: "Password" }).fill("shift-qa");
    await page.getByRole("button", { name: "Log in" }).click();
    await page.waitForURL(/\/odoo/);

    // 2. Open the Maintenance app and create a new request (no team chosen).
    await page.getByTitle("Home Menu").click();
    await page.getByRole("menuitem", { name: "Maintenance" }).click();
    await page.getByRole("button", { name: "Maintenance" }).click();
    await page.getByRole("menuitem", { name: "Maintenance Requests" }).click();
    await page.getByRole("button", { name: "New" }).click();
    await page.getByRole("textbox", { name: "Request" }).fill("Abnormal vibration on stand F3 · TEST1");
    await page.getByRole("combobox", { name: "Equipment" }).fill("Stand F3");
    await page.getByRole("option", { name: /Finishing mill · Stand F3/ }).click();

    // 3. Type = Corrective, Priority = highest (3rd star), and save.
    await page.getByRole("radio", { name: "Corrective" }).click();
    await page.getByRole("radio", { name: "High" }).click();
    // Clicking the priority widget autosaves the record; save explicitly if still dirty.
    const saveButton = page.getByRole("button", { name: "Save manually" });
    if (await saveButton.isVisible()) {
      await saveButton.click();
    }

    // Expected: record saved, stage "New Request" current.
    await expect(page).toHaveURL(/\/odoo\/maintenance-requests\/\d+/);
    await expect(page.getByRole("radio", { name: "New Request" })).toBeChecked();
    await expect(page.getByRole("radio", { name: "High" })).toBeChecked();

    // Expected: Team filled automatically from the equipment.
    await expect(page.getByRole("combobox", { name: "Team" })).toHaveValue("Rolling mill maintenance");

    // Expected: requester is the Shift Supervisor. The form has no "Created by" field,
    // so this is asserted on the creation message posted in the chatter.
    await expect(
      page.getByRole("group", { name: "System notification" }).filter({ hasText: "Maintenance Request created" }),
    ).toContainText("Shift Supervisor");
  });
});
